        <Space direction="vertical" gap="xxxxl" className={styles.article}>
          {sections.map(({ id, title, level = 1, body }) => (
            <Space key={id} direction="vertical" gap="md">
              <Heading level={(level + 1) as 2 | 3 | 4} id={id}>
                {title}
              </Heading>
              {body.map((paragraph) => (
                <Text as="p" key={paragraph}>
                  {paragraph}
