import { Code, Space } from '@korzun/design/component';
import { Button } from '@korzun/design/control';
import { CheckIcon } from '@korzun/design/icon';
import { createUseStyles } from '@korzun/design/theme';
import { useEffect, useRef, useState } from 'react';

// In your app this goes in a sibling style.ts.
const useStyle = createUseStyles({
  // Reserves the widest label ("Could not copy"), so the row keeps its width as the label changes.
  button: { minWidth: '10em' },
  // Visually hidden, but read aloud by screen readers.
  status: {
    position: 'absolute',
    width: 1,
    height: 1,
    overflow: 'hidden',
    clipPath: 'inset(50%)',
    whiteSpace: 'nowrap',
  },
});

type State = 'idle' | 'done' | 'failed';

const RESET_MS = 2000;

// Copy this component into your app.
function CopyButton({ text }: { text: string }) {
  const styles = useStyle();
  const [state, setState] = useState<State>('idle');
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      clearTimeout(timer.current);
    };
  }, []);

  const show = (next: State) => {
    // A write that settles after unmount must not set state or start a timer.
    if (!mounted.current) return;
    // Pressing again restarts the two seconds.
    clearTimeout(timer.current);
    setState(next);
    timer.current = setTimeout(() => setState('idle'), RESET_MS);
  };

  const copy = () => {
    // A missing clipboard (outside a secure context, e.g. a dev server on a LAN address) or a
    // synchronous throw from writeText lands in the same failed path as a rejection.
    Promise.resolve()
      .then(() => navigator.clipboard.writeText(text))
      .then(
        () => show('done'),
        () => show('failed')
      );
  };

  const message = state === 'done' ? 'Copied' : state === 'failed' ? 'Could not copy' : '';
  return (
    <>
      <Button
        type="text"
        // The label is the name while idle; the changing text names it after.
        ariaLabel={state === 'idle' ? 'Copy' : undefined}
        prefix={state === 'done' ? CheckIcon : undefined}
        className={styles.button}
        onClick={copy}
      >
        {state === 'idle' ? 'Copy' : message}
      </Button>
      {/* Always mounted, so a screen reader announces the text when it appears. */}
      <span role="status" className={styles.status}>
        {message}
      </span>
    </>
  );
}

export default function CopyButtonExample() {
  return (
    <Space gap="md">
      <Code>postgres://app@db.internal:5432/app</Code>
      <CopyButton text="postgres://app@db.internal:5432/app" />
    </Space>
  );
}

import { Card, Page, Space } from '@korzun/design/component';
import { Button, TextInput } from '@korzun/design/control';
import { createUseStyles, type Theme } from '@korzun/design/theme';
import { useToast } from '@korzun/design/toast';
import { useState } from 'react';

// In your app this goes in a sibling style.ts.
const useStyle = createUseStyles((theme: Theme) => ({
  // Centring a column in the viewport is the one layout Space can't express.
  screen: {
    display: 'grid',
    placeItems: 'center',
    // A shrinkable track, so the column's maxWidth holds on a narrow screen.
    gridTemplateColumns: 'minmax(0, 1fr)',
    minHeight: '100vh',
    boxSizing: 'border-box',
    padding: `0 ${theme.space.xxl}`,
  },
  column: {
    width: theme.layout.formWidth,
    maxWidth: '100%',
  },
}));

// Stands in for your auth call.
const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export default function SignIn() {
  const styles = useStyle();
  const toast = useToast();
  const [username, setUsername] = useState<string | undefined>();
  const [password, setPassword] = useState<string | undefined>();

  // A form action: the submit Button shows its spinner while this runs.
  const signIn = async () => {
    await wait(600);
    toast('Signed in', 'success');
  };

  return (
    <Page type="minimal">
      <div className={styles.screen}>
        <Space direction="vertical" gap="xxl" className={styles.column}>
          <Card>
            <form action={signIn}>
              <Space direction="vertical" gap="xxl">
                <Space direction="vertical" gap="md">
                  <TextInput
                    name="username"
                    placeholder="Username or email"
                    autoCapitalize="none"
                    autoComplete="username"
                    value={username}
                    onChange={setUsername}
                  />
                  <TextInput
                    name="password"
                    placeholder="Password"
                    password
                    autoComplete="current-password"
                    value={password}
                    onChange={setPassword}
                  />
                </Space>
                <Button type="primary" submit>
                  Sign In
                </Button>
              </Space>
            </form>
          </Card>
          <Button onClick={() => toast('Check your email for a reset link', 'info')}>
            Forgot password?
          </Button>
        </Space>
      </div>
    </Page>
  );
}

import { Card, ProgressCircle, Space, Text } from '@korzun/design/component';

// Copy this component into your app.
function ReadingProgress({ value, title }: { value: number; title: string }) {
  // A cleared field or a missing value reads as not started.
  if (!Number.isFinite(value) || value <= 0) {
    return <Text tone="muted">Not started</Text>;
  }
  if (value >= 1) {
    return <Text tone="muted">Completed</Text>;
  }
  return <ProgressCircle value={value} size={16} ariaLabel={`Reading progress for ${title}`} />;
}

const BOOKS = [
  { title: 'Middlemarch', progress: 0.42 },
  { title: 'Persuasion', progress: 1 },
  { title: 'Villette', progress: 0 },
  { title: 'North and South', progress: 0.08 },
];

export default function ReadingProgressRecipe() {
  return (
    <Card title="Reading">
      <Space direction="vertical" gap="sm">
        {BOOKS.map((book) => (
          <Space key={book.title} justify="between">
            <Text weight="semibold">{book.title}</Text>
            <ReadingProgress value={book.progress} title={book.title} />
          </Space>
        ))}
      </Space>
    </Card>
  );
}
